window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-100"]=[{"id":"set2-Q50hhEVE","fingerprint":"0e446dfcb360ebac","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt obiectivele principale ale obturației de canal în cadrul tratamentului endodontic?","options":[{"id":"A","text":"Asigurarea unei sigilări tridimensionale etanșe a sistemului endodontic."},{"id":"B","text":"Crearea unui mediu favorabil pentru cicatrizarea apicală."},{"id":"C","text":"Menținerea unei comunicări minime cu spațiul periapical pentru drenaj."},{"id":"D","text":"Stimularea fenomenelor de percolație pentru o mai bună adaptare a materialului."},{"id":"E","text":"Întreruperea căilor de comunicare dintre sistemul endodontic și țesuturile parodontale."}],"correct":["A","B","E"],"pages":[151],"source":"set-2"},{"id":"set2-dAEX6Gjq","fingerprint":"fbf0316d527a57de","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce factori influențează decizia de a realiza obturația de canal în aceeași ședință cu tratamentul chemo-mecanic sau într-o ședință ulterioară?","options":[{"id":"A","text":"Statusul pulpar și periapical evaluat clinic și imagistic."},{"id":"B","text":"Preferința medicului pentru o anumită tehnică de obturare."},{"id":"C","text":"Exclusiv tipul de material de obturație utilizat."},{"id":"D","text":"Vârsta și sexul pacientului."},{"id":"E","text":"Costul total al tratamentului endodontic."}],"correct":["A"],"pages":[151],"source":"set-2"},{"id":"set2-zY-CSQ3G","fingerprint":"40959172524946ac","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"În ce situații clinice se consideră că obturația de canal poate fi realizată în aceeași ședință cu tratamentul chemo-mecanic?","options":[{"id":"A","text":"La un dinte vital cu patologie pulpară."},{"id":"B","text":"La un dinte vital care nu prezintă patologie pulpară."},{"id":"C","text":"În prezența unui abces periapical acut."},{"id":"D","text":"Când există o hemoragie necontrolabilă din spațiul periapical."},{"id":"E","text":"La un dinte devital care este asimptomatic."}],"correct":["A","B","E"],"pages":[151],"source":"set-2"},{"id":"set2-E4u_vnUu","fingerprint":"1d15f1d95ec4ac2b","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele condiții reprezintă motive pentru temporizarea realizării obturației de canal?","options":[{"id":"A","text":"Prezența edemului și a sensibilității la un dinte cu parodontită apicală acută."},{"id":"B","text":"Tratamentul unui dinte devital asimptomatic."},{"id":"C","text":"Lipsa timpului necesar pentru a finaliza tratamentul în condiții optime."},{"id":"D","text":"Imposibilitatea de a usca canalele radiculare din cauza unei secreții persistente."},{"id":"E","text":"Tratamentul unui dinte vital cu patologie pulpară."}],"correct":["A","C","D"],"pages":[151],"source":"set-2"},{"id":"set2-pcSPwUsf","fingerprint":"ebbe3ae426b6497a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este limita apicală a obturației de canal acceptată în principiu?","options":[{"id":"A","text":"Exact la nivelul foramenului apical."},{"id":"B","text":"La nivelul joncțiunii cemento-dentinare, care corespunde întotdeauna cu constricția apicală."},{"id":"C","text":"La o distanță de 1 mm de apexul radiologic."},{"id":"D","text":"La 0,5 mm de apexul radicular."},{"id":"E","text":"La o distanță de 2,5 mm de apexul radicular."}],"correct":["C"],"pages":[151],"source":"set-2"},{"id":"set2-lhJ90fL_","fingerprint":"2d3e325ff1884974","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații despre reperele anatomice apicale este corectă?","options":[{"id":"A","text":"Joncțiunea cemento-dentinară corespunde întotdeauna din punct de vedere topografic cu constricția apicală."},{"id":"B","text":"Foramenul apical se poate afla la o distanță variabilă, cuprinsă între 0 și 2,5 mm, față de apexul radicular."},{"id":"C","text":"Constricția apicală prezintă întotdeauna un aspect anatomic conicizat, cu pereți dentinari paraleli."},{"id":"D","text":"Joncțiunea cemento-dentinară reprezintă o delimitare histologică ce nu poate fi determinată clinic."},{"id":"E","text":"Constricția apicală este situată la o distanță medie de 0,5 mm de foramenul apical."}],"correct":["B","D","E"],"pages":[151],"source":"set-2"},{"id":"set2-s2-JPnVo","fingerprint":"cc5bcf5eecb583dc","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este limita apicală a obturației de canal acceptată în principiu în practica clinică?","options":[{"id":"A","text":"La nivelul foramenului apical, pentru a asigura o sigilare completă."},{"id":"B","text":"La o distanță de 1 mm față de apexul radiologic."},{"id":"C","text":"Exact la nivelul constricției apicale, aflată la 0,5 mm de foramen."},{"id":"D","text":"La o distanță variabilă, între 0 și 2,5 mm de apexul radicular."},{"id":"E","text":"La nivelul joncțiunii cemento-dentinare, determinată histologic."}],"correct":["B"],"pages":[152],"source":"set-2"},{"id":"set2-fSRa4SL3","fingerprint":"16d70aaabf710729","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații referitoare la anatomia apicală sunt corecte?","options":[{"id":"A","text":"Constricția apicală poate prezenta un aspect anatomic multiplu sau cu pereți paraleli."},{"id":"B","text":"Foramenul apical este situat la o distanță fixă de 2,5 mm față de apexul radicular."},{"id":"C","text":"Constricția apicală se află, în medie, la 0,5 mm de foramenul apical."},{"id":"D","text":"Joncțiunea cemento-dentinară corespunde întotdeauna cu constricția apicală."},{"id":"E","text":"Fenomenele de resorbție radiculară simplifică determinarea limitei apicale."}],"correct":["A","C"],"pages":[152],"source":"set-2"},{"id":"set2-Jr8JToWX","fingerprint":"58fc3ad7d14fc2f1","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Pe ce se bazează obținerea succesului unui tratament endodontic modern?","options":[{"id":"A","text":"Realizarea unei obturații de canal tridimensionale etanșe."},{"id":"B","text":"Menținerea unui strat subțire de smear-layer pentru a proteja dentina."},{"id":"C","text":"Prepararea și curățarea riguroasă a canalelor radiculare."},{"id":"D","text":"Utilizarea exclusivă a materialelor de obturație cu proprietăți dezinfectante puternice."},{"id":"E","text":"Dezinfecția avansată a sistemului endodontic prin irigare modernă și activarea soluțiilor."}],"correct":["A","C","E"],"pages":[152],"source":"set-2"},{"id":"set2-hCCAmnhM","fingerprint":"cd737679960dd860","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt condițiile pe care trebuie să le îndeplinească un canal radicular pentru a fi pregătit pentru obturație?","options":[{"id":"A","text":"În cazul reluării tratamentului, resturile vechi de material pot rămâne dacă sunt la apex."},{"id":"B","text":"Canalul trebuie să fie permeabil pe toată lungimea de lucru."},{"id":"C","text":"Prezența detritusurilor (smear-layer) este acceptabilă dacă se folosește un sealer adeziv."},{"id":"D","text":"Decontaminarea este necesară doar dacă există o leziune periapicală vizibilă radiologic."},{"id":"E","text":"Canalul trebuie să fie uscat."}],"correct":["B","E"],"pages":[152],"source":"set-2"},{"id":"set2--THkqc_Y","fingerprint":"8c070d4ef58abf8c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele caracteristici NU este o calitate a unui material ideal de obturație de canal?","options":[{"id":"A","text":"Stabilitate dimensională."},{"id":"B","text":"Resorbabil."},{"id":"C","text":"Aderența la pereții canalului radicular."},{"id":"D","text":"Radioopacitate."},{"id":"E","text":"Insolubilitate în fluidele tisulare."}],"correct":["B"],"pages":[152],"source":"set-2"},{"id":"set2-mfgNhHkT","fingerprint":"fb06c6d803e72c16","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce roluri îndeplinește componenta \"sealer\" în cadrul unei obturații de canal?","options":[{"id":"A","text":"Este singura componentă responsabilă de caracterul antimicrobian al obturației."},{"id":"B","text":"Perfectează adaptarea materialului solid sau semi-solid la pereții canalului și acționează ca lubrifiant."},{"id":"C","text":"Asigură stabilitatea dimensională a întregii obturații, prevenind contracția."},{"id":"D","text":"Se transformă dintr-o formă solidă într-una semi-solidă după introducerea în canal."},{"id":"E","text":"Ocupă cea mai mare parte a spațiului endodontic, formând componenta \"core\"."}],"correct":["B"],"pages":[152],"source":"set-2"},{"id":"set2-477wwc7r","fingerprint":"5b29e206abeed029","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt motivele pentru care conurile de argint nu mai sunt recomandate în tratamentul endodontic?","options":[{"id":"A","text":"Caracterul lor corodabil, cu eliberarea de compuși citotoxici."},{"id":"B","text":"Utilizarea lor frecventă în contextul unei instrumentări și debridări endodontice insuficiente."},{"id":"C","text":"Incapacitatea de a fi utilizate în canalele radiculare curbe și de calibru mic."},{"id":"D","text":"Lipsa totală de radioopacitate, îngreunând evaluarea radiologică."},{"id":"E","text":"Biocompatibilitate superioară gutapercii, ceea ce le face prea costisitoare."}],"correct":["A","B"],"pages":[153],"source":"set-2"},{"id":"set2-gQW-B3VY","fingerprint":"e24dd0cf2d3d122e","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Conform compoziției gutapercii de uz endodontic, care component se găsește în proporția cea mai mare?","options":[{"id":"A","text":"Coloranți organici"},{"id":"B","text":"Ceruri și rășini"},{"id":"C","text":"Gutaperca"},{"id":"D","text":"Sulfați metalici"},{"id":"E","text":"Oxid de zinc"}],"correct":["E"],"pages":[153],"source":"set-2"},{"id":"set2-l1K-ecuC","fingerprint":"78adc161532a2ef8","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce caracteristică este specifică formei cristaline β a gutapercii?","options":[{"id":"A","text":"Este principalul constituent al capsulelor de gutapercă fluidă la rece."},{"id":"B","text":"Prezintă o solubilitate crescută în apă și alcool."},{"id":"C","text":"Din aceasta se realizează conurile de gutapercă folosite în metodele aplicate la temperatură obișnuită."},{"id":"D","text":"Este utilizată cu precădere în tehnicile de obturare termoplastice."},{"id":"E","text":"Este extrasă direct din seva arborelui Palaquium Gutta, fără a necesita procesare."}],"correct":["C"],"pages":[153],"source":"set-2"},{"id":"set2-a9jru6JW","fingerprint":"00ab37252849d841","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect proprietățile și avantajele gutapercii?","options":[{"id":"A","text":"Este un material termoplastifiabil, fiind adecvat pentru tehnicile de obturare la cald."},{"id":"B","text":"Conținutul său redus de oxid de zinc îi conferă o toleranță excelentă în țesuturile periapicale."},{"id":"C","text":"Este solubilă în solvenți precum cloroformul și eucaliptolul."},{"id":"D","text":"Formează o adeziune chimică puternică la pereții canalului radicular, asigurând o sigilare perfectă."},{"id":"E","text":"Prezintă stabilitate dimensională și este non-resorbabilă."}],"correct":["A","C","E"],"pages":[153],"source":"set-2"},{"id":"set2-l4YWePFQ","fingerprint":"fbdfbaf36ffeecb9","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este principalul dezavantaj al gutapercii care poate compromite sigilarea spațiului endodontic?","options":[{"id":"A","text":"Caracterul său iritant cauzat de sulfații metalici din compoziție."},{"id":"B","text":"Absența unei adeziuni chimice la sealer sau la pereții canalului radicular."},{"id":"C","text":"Dificultatea de a fi dezinfectată înainte de utilizare."},{"id":"D","text":"Resorbția rapidă în prezența fluidelor tisulare."},{"id":"E","text":"Instabilitatea dimensională la variațiile de temperatură."}],"correct":["B"],"pages":[153],"source":"set-2"},{"id":"set2-UPaxrjHa","fingerprint":"29e8bec73812ceed","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce tipuri de modificări pot fi aduse gutapercii pentru a-i îmbunătăți proprietățile adezive sau antimicrobiene?","options":[{"id":"A","text":"Îmbogățirea compoziției cu nanoparticule."},{"id":"B","text":"Înlocuirea sulfaților metalici cu coloranți organici pentru a crește radioopacitatea."},{"id":"C","text":"Adăugarea de substanțe cu caracter antimicrobian, precum clorhexidina sau hidroxidul de calciu."},{"id":"D","text":"Impregnarea suprafeței exterioare a conurilor cu glasionomeri, rășini sau bioceramică."},{"id":"E","text":"Creșterea procentului de oxid de zinc pentru a spori biocompatibilitatea."}],"correct":["A","C","D"],"pages":[153],"source":"set-2"},{"id":"set2-jza3abHV","fingerprint":"c35a9a0f4720f452","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este protocolul recomandat pentru dezinfectarea conurilor de gutapercă?","options":[{"id":"A","text":"Imersie în NaOCl 5,25% timp de 60 de secunde."},{"id":"B","text":"Imersie în alcool pentru 5 minute."},{"id":"C","text":"Imersie în eucaliptol timp de 1 minut."},{"id":"D","text":"Imersie în NaOCl 5,25% timp de 10 minute."},{"id":"E","text":"Sterilizare în autoclav la 121°C."}],"correct":["A"],"pages":[153],"source":"set-2"},{"id":"set2-GJBLscKY","fingerprint":"1b1bd7b0acafe898","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele componente se regăsesc în compoziția materialelor de tip Resilon și RealSeal?","options":[{"id":"A","text":"Sticlă bioactivă"},{"id":"B","text":"Fosfat tricalcic"},{"id":"C","text":"Rășini epoxidice"},{"id":"D","text":"Eugenol"},{"id":"E","text":"Policaprolactonă (PCL)"}],"correct":["A","B","E"],"pages":[154],"source":"set-2"},{"id":"set2-wBAjsUbP","fingerprint":"bbb343048fc4dfc7","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care a fost obiectivul principal urmărit prin introducerea materialelor de tip Resilon și RealSeal în endodonție?","options":[{"id":"A","text":"Crearea unei obturații de canal de tip monobloc prin adeziune"},{"id":"B","text":"Creșterea solubilității materialului de obturație în fluidele tisulare"},{"id":"C","text":"Asigurarea unui rol exclusiv lubrifiant pentru facilitarea inserării conurilor"},{"id":"D","text":"Înlocuirea completă a sigilanților endodontici"},{"id":"E","text":"Asigurarea resorbției materialului în cazul extruziei în țesuturile periapicale"}],"correct":["A"],"pages":[154],"source":"set-2"},{"id":"set2-eU9l4Zg1","fingerprint":"482aa08bc6292716","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce roluri îndeplinesc sigilanții (sealerii) endodontici în cadrul obturației de canal?","options":[{"id":"A","text":"Completarea microspațiilor dintre materialul de obturație și pereții canalelor radiculare"},{"id":"B","text":"Prevenirea sau minimizarea microinfiltrațiilor"},{"id":"C","text":"Asigurarea contracției la priză pentru a crea spațiu de sigilare"},{"id":"D","text":"Facilitarea introducerii conurilor de gutapercă printr-un rol lubrifiant"},{"id":"E","text":"Inducerea capacității discromice asupra dentinei pentru a marca obturația"}],"correct":["A","B","D"],"pages":[154],"source":"set-2"},{"id":"set2-A4HtRt1y","fingerprint":"b3fc0452137d4899","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele sunt considerate calități ale unui sealer endodontic ideal?","options":[{"id":"A","text":"Solubilitate în lichidele tisulare"},{"id":"B","text":"Ușor de îndepărtat în caz de necesitate a reluării tratamentului"},{"id":"C","text":"Aderență la pereții parietali ai canalelor radiculare"},{"id":"D","text":"Priză cu contracție semnificativă"},{"id":"E","text":"Capacitatea de a induce colorații la nivelul dentinei"}],"correct":["B","C"],"pages":[154],"source":"set-2"},{"id":"set2-kXkMKvcL","fingerprint":"3d2ef92b830e36f8","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele afirmații descriu corect dezavantajele sigilanților pe bază de zinc-oxid eugenol (ZOE)?","options":[{"id":"A","text":"Sunt insolubili în contact cu fluidele organismului"},{"id":"B","text":"Pot induce colorații la nivelul țesuturilor dentare"},{"id":"C","text":"Preparatele care conțin formaldehidă sunt lipsite de citotoxicitate"},{"id":"D","text":"Au un timp de lucru insuficient"},{"id":"E","text":"Eugenolul din compoziție are un efect calmant asupra parodonțiului"}],"correct":["B"],"pages":[154],"source":"set-2"},{"id":"set2-u9rO2tsF","fingerprint":"dc09b2ec28adfd64","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Conform clasificării bazate pe compoziția chimică, care dintre următoarele reprezintă clase de sigilanți endodontici?","options":[{"id":"A","text":"Sigilanți pe bază de rășini epoxidice"},{"id":"B","text":"Sigilanți pe bază de policaprolactonă (PCL)"},{"id":"C","text":"Sigilanți pe bază de sulfat de bariu"},{"id":"D","text":"Sigilanți pe bază de hidroxid de calciu"},{"id":"E","text":"Sigilanți bioceramici"}],"correct":["A","D","E"],"pages":[154],"source":"set-2"},{"id":"set2-Igwr71q0","fingerprint":"127efc6b89a19d34","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele reprezintă avantaje ale sigilanților pe bază de hidroxid de calciu?","options":[{"id":"A","text":"Stimulează regenerarea osoasă și favorizează vindecarea leziunilor periradiculare."},{"id":"B","text":"Sunt mai puțin iritanți decât sigilanții pe bază de oxid de zinc-eugenol (ZOE)."},{"id":"C","text":"Prezintă o stabilitate dimensională bună și o solubilitate redusă."},{"id":"D","text":"Prezintă un efect antibacterian datorită pH-ului alcalin."},{"id":"E","text":"Au o adeziune foarte bună la pereții canalului radicular."}],"correct":["A","B","D"],"pages":[155],"source":"set-2"},{"id":"set2-2urrvqd6","fingerprint":"a80c7e2b2c57af80","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce dezavantaj major este asociat cu reacția de priză a sigilanților pe bază de rășini epoxidice?","options":[{"id":"A","text":"O contracție de priză crescută, cu risc de detașare."},{"id":"B","text":"Contracție de priză absentă, ceea ce duce la instabilitate volumetrică."},{"id":"C","text":"Sensibilitate la prezența umidității și a oxigenului."},{"id":"D","text":"Eliberarea de formaldehidă, care le conferă citotoxicitate."},{"id":"E","text":"O reacție de priză neomogenă, materialul rămânând păstos."}],"correct":["D"],"pages":[155],"source":"set-2"},{"id":"set2-cwsvGFI4","fingerprint":"e87959d5a38cd721","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care afirmație descrie corect o diferență între sigilanții pe bază de rășini metacrilice și cei pe bază de rășini epoxidice în situația reluării tratamentului endodontic?","options":[{"id":"A","text":"Ambele tipuri de rășini sunt la fel de dificil de îndepărtat ca materialele siliconice."},{"id":"B","text":"Rășinile metacrilice nu pot fi îndepărtate, spre deosebire de cele epoxidice."},{"id":"C","text":"Rășinile epoxidice sunt mai ușor de îndepărtat datorită solubilității lor ridicate."},{"id":"D","text":"Rășinile metacrilice sunt mai ușor de îndepărtat din canal decât rășinile epoxidice."},{"id":"E","text":"Îndepărtarea rășinilor epoxidice este facilitată de lipsa lor de adeziune la pereții canalului."}],"correct":["D"],"pages":[155],"source":"set-2"},{"id":"set2-bKS8Ikkw","fingerprint":"861a518a0ad3d65a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt dezavantajele asociate cu sigilanții pe bază de rășini metacrilice?","options":[{"id":"A","text":"Sunt dificil de îndepărtat în totalitate, similar cu sigilanții siliconici."},{"id":"B","text":"Monomerii nepolimerizați pot exercita toxicitate asupra țesuturilor periapicale."},{"id":"C","text":"Au o solubilitate crescută în timp, favorizând microinfiltrația."},{"id":"D","text":"Mecanismul de priză este complex și sensibil la prezența umidității și a oxigenului."},{"id":"E","text":"Prezintă o contracție de priză crescută, cu riscul detașării materialului de obturație."}],"correct":["B","D","E"],"pages":[155],"source":"set-2"},{"id":"set2-v6xlgAbf","fingerprint":"feb78827dbad874d","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce caracteristici sunt considerate avantaje ale sigilanților bazați pe materiale siliconice?","options":[{"id":"A","text":"Efect antibacterian de lungă durată datorită pH-ului."},{"id":"B","text":"Penetrabilitate excelentă în tubulii dentinari."},{"id":"C","text":"Contracția de priză absentă și stabilitatea volumetrică."},{"id":"D","text":"Adeziune foarte bună și conferirea etanșeității."},{"id":"E","text":"Ușurința îndepărtării în caz de reluare a tratamentului."}],"correct":["C","D"],"pages":[155],"source":"set-2"},{"id":"set2-OdOdszJu","fingerprint":"031507773680de8c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce tip de sigilant permite obținerea unei obturații de tip monobloc în asociere cu conurile Resilon?","options":[{"id":"A","text":"Sigilanții bazați pe rășini metacrilice."},{"id":"B","text":"Sigilanții bazați pe materiale siliconice."},{"id":"C","text":"Sigilanții pe bază de ZOE."},{"id":"D","text":"Sigilanții pe bază de rășini epoxidice."},{"id":"E","text":"Sigilanții pe bază de hidroxid de calciu."}],"correct":["A"],"pages":[155],"source":"set-2"},{"id":"set2-Kijx4sde","fingerprint":"944c2ceb5188e7bf","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la avantajele sigilanților bazați pe materiale bioceramice?","options":[{"id":"A","text":"Realizează o adeziune chimică la pereții canalului radicular."},{"id":"B","text":"Sunt insolubile și stabile dimensional."},{"id":"C","text":"Prezintă un efect antibacterian de lungă durată, inclusiv împotriva E. Faecalis."},{"id":"D","text":"Prezintă o contracție de priză minimă, dar prezentă clinic."},{"id":"E","text":"Sunt materiale hidrofobe, ceea ce previne contaminarea cu fluide din tubulii dentinari."}],"correct":["A","B","C"],"pages":[156],"source":"set-2"},{"id":"set2-GJGA2MAK","fingerprint":"e00ccd1290d5e691","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce componente intră în compoziția sigilanților bazați pe materiale bioceramice?","options":[{"id":"A","text":"Ionomer de sticlă modificat cu rășini și acid poliacrilic."},{"id":"B","text":"Oxid de zinc, eugenol și rășini hidrogenate."},{"id":"C","text":"Silicați dicalcici și tricalcici, hidroxid de calciu și oxid de zirconiu."},{"id":"D","text":"Poliizopren, săruri de bariu și dioxid de titan."},{"id":"E","text":"Rășini epoxidice, bismut și particule de argint."}],"correct":["C"],"pages":[156],"source":"set-2"},{"id":"set2-B6nnXzH-","fingerprint":"bc497811d6500014","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce implicație clinică directă are caracterul hidrofil al sigilanților bioceramici?","options":[{"id":"A","text":"Necesită aplicarea unui agent de adeziune specific pe pereții canalului."},{"id":"B","text":"Uscarea excesivă a canalului radicular este contraindicată."},{"id":"C","text":"Sunt solubile în prezența umidității, compromițând sigilarea."},{"id":"D","text":"Sunt compatibile doar cu tehnicile de obturare la cald, care elimină umiditatea."},{"id":"E","text":"Timpul de priză este accelerat în canalele complet uscate."}],"correct":["B"],"pages":[156],"source":"set-2"},{"id":"set2-Zz-ucoqv","fingerprint":"f6d448a6e3da323f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații despre Mineral Trioxide Aggregate (MTA) sunt corecte?","options":[{"id":"A","text":"Este un material hidrofil, care face priză într-un mediu umed."},{"id":"B","text":"A fost introdus în practica stomatologică de Torabinejad în 1983."},{"id":"C","text":"Este considerat un material dificil de aplicat."},{"id":"D","text":"Prezintă un pH neutru de aproximativ 7,0."},{"id":"E","text":"Este foarte util în situațiile ce necesită apexificare."}],"correct":["A","C","E"],"pages":[156],"source":"set-2"},{"id":"set2-YBhFlitQ","fingerprint":"a3e10d6ff396cca8","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este principiul fundamental legat de cantitatea relativă de gutapercă și sigilant în obturația de canal?","options":[{"id":"A","text":"O obturație densă și omogenă se obține folosind exclusiv sigilant, fără gutapercă."},{"id":"B","text":"Raportul volumetric dintre sigilant și gutapercă trebuie să fie de 1:1 pentru a obține o obturație omogenă."},{"id":"C","text":"Cantitatea de sigilant utilizată trebuie să fie minimă, gutaperca fiind materialul principal de umplere a canalului."},{"id":"D","text":"Sigilantul trebuie să ocupe cea mai mare parte a sistemului endodontic pentru a asigura o sigilare chimică perfectă."},{"id":"E","text":"Gutaperca acționează doar ca un piston pentru a împinge sigilantul în ramificațiile apicale, cantitatea sa fiind neimportantă."}],"correct":["C"],"pages":[156],"source":"set-2"},{"id":"set2-QO1tqG_M","fingerprint":"debd50c217c178b2","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este principalul criteriu de clasificare a tehnicilor de obturare a canalelor radiculare bazate pe utilizarea gutapercii?","options":[{"id":"A","text":"Preferințele medicului și particularitățile cazului clinic."},{"id":"B","text":"Direcția de exercitare a forțelor de condensare, strict verticală sau strict laterală."},{"id":"C","text":"Temperatura la care este utilizată gutaperca."},{"id":"D","text":"Tipul de sigilant folosit în combinație cu gutaperca."},{"id":"E","text":"Numărul de conuri de gutapercă utilizate în timpul obturației."}],"correct":["C"],"pages":[156],"source":"set-2"},{"id":"set2-FiX9CCLG","fingerprint":"7d382c01636e625f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce se poate afirma despre comparația rezultatelor obținute prin aplicarea diferitelor tehnici contemporane de obturație de canal?","options":[{"id":"A","text":"Tehnica de condensare laterală la rece este considerată universal superioară tuturor celorlalte metode."},{"id":"B","text":"Nu există diferențe semnificative între tehnici, deși unele studii sugerează o superioritate a condensării verticale la cald."},{"id":"C","text":"Selecția tehnicii se bazează exclusiv pe caracteristicile sistemului endodontic, fără a fi influențată de pregătirea medicului."},{"id":"D","text":"Toate tehnicile de condensare ”la cald” oferă rezultate net superioare celor ”la rece”, indiferent de caz."},{"id":"E","text":"Rezultatele depind exclusiv de tipul de sigilant, tehnica de obturare având un rol secundar."}],"correct":["B"],"pages":[156],"source":"set-2"},{"id":"set2-cdBDwlHE","fingerprint":"0483d7a14f64701a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt elementele utilizate în tehnica de condensare laterală la rece?","options":[{"id":"A","text":"Un con de gutapercă master de conicitate standardizată ISO."},{"id":"B","text":"Conuri de gutapercă accesorii standardizate ISO."},{"id":"C","text":"Sigilant apical (sealer)."},{"id":"D","text":"Instrumentar rotativ specific, denumit spreadere."},{"id":"E","text":"Conuri de gutapercă accesorii nestandardizate."}],"correct":["A","C","E"],"pages":[157],"source":"set-2"},{"id":"set2-N3xMrNMU","fingerprint":"7ab100d92a3d9669","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce avantaj distinctiv prezintă finger spreaderele în comparație cu hand spreaderele în tehnica de condensare laterală la rece?","options":[{"id":"A","text":"Sunt fabricate dintr-un material mai rigid, prevenind fracturarea."},{"id":"B","text":"Conferă o mai mare sensibilitate tactilă și se îndepărtează cu ușurință din canal."},{"id":"C","text":"Permit rotirea doar într-un singur sens pentru o condensare optimă."},{"id":"D","text":"Sunt destinate exclusiv canalelor cu curburi accentuate."},{"id":"E","text":"Permit aplicarea unei presiuni de condensare superioare."}],"correct":["B"],"pages":[157],"source":"set-2"},{"id":"set2-q-e3MW86","fingerprint":"a303514019348819","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următorii factori pot conduce la apariția de spații libere în obturația de canal realizată prin condensare laterală la rece?","options":[{"id":"A","text":"O conicitate insuficientă a preparației radiculare."},{"id":"B","text":"Utilizarea unui con master de gutapercă cu o conicitate mai mare de 2%."},{"id":"C","text":"Folosirea unui sigilant cu priză rapidă."},{"id":"D","text":"Prezența unor curburi accentuate ale canalului radicular."},{"id":"E","text":"O presiune de condensare inadecvată."}],"correct":["A","D","E"],"pages":[157],"source":"set-2"},{"id":"set2-4AXQKo8N","fingerprint":"247ed5ba865247c4","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce caracteristică a gutapercii este esențială în tehnica de condensare laterală și care este o consecință a acesteia în timpul procedurii?","options":[{"id":"A","text":"Rigiditatea sa, care previne depășirea apicală."},{"id":"B","text":"Biocompatibilitatea sa, care asigură o bună sigilare apicală."},{"id":"C","text":"Solubilitatea sa, care permite o adeziune chimică la sigilant."},{"id":"D","text":"Caracterul viscoelastic, care implică tendința de revenire la forma inițială după îndepărtarea spreaderului."},{"id":"E","text":"Termoplasticitatea sa, care permite confluarea conurilor într-o masă omogenă."}],"correct":["D"],"pages":[157],"source":"set-2"},{"id":"set2-pGNZ7YfA","fingerprint":"5aac11ffd73b3d1e","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu dezavantajele tehnicii de condensare laterală la rece?","options":[{"id":"A","text":"Este dificil de realizat în cazul canalelor lungi cu curburi accentuate."},{"id":"B","text":"Conurile de gutapercă nu confluează într-o masă compactă și omogenă."},{"id":"C","text":"Este o tehnică rapidă, dar cu costuri ridicate."},{"id":"D","text":"Asigură o sigilare optimă a canalelor laterale și accesorii prin pătrunderea gutapercii."},{"id":"E","text":"Condensarea este dificil de realizat în porțiunea apicală a canalului."}],"correct":["A","B","E"],"pages":[157],"source":"set-2"},{"id":"set2-ZCN7mRVP","fingerprint":"fe3087cacdb17ee7","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce rezultat se obține frecvent în treimea apicală a canalului la utilizarea tehnicii de condensare laterală la rece?","options":[{"id":"A","text":"O masă compactă și omogenă de gutapercă ce sigilează perfect apexul."},{"id":"B","text":"Umplerea canalelor laterale și accesorii cu gutapercă datorită presiunii de condensare."},{"id":"C","text":"Un con unic parțial înconjurat de o cantitate redusă de sealer."},{"id":"D","text":"O condensare a multiplelor conuri accesorii ce umplu complet spațiul."},{"id":"E","text":"O cantitate mare de sigilant care compensează lipsa condensării laterale."}],"correct":["C"],"pages":[157],"source":"set-2"},{"id":"set2-OZqV6nv2","fingerprint":"96af832993fdf10f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În ce situație clinică specifică NU este recomandată tehnica de condensare laterală la rece?","options":[{"id":"A","text":"Prezența canalelor laterale sau accesorii."},{"id":"B","text":"Utilizarea sistemelor de instrumentare rotativă."},{"id":"C","text":"Canale radiculare cu curburi accentuate."},{"id":"D","text":"Canale radiculare largi și drepte."},{"id":"E","text":"Preparații radiculare fără stop apical."}],"correct":["E"],"pages":[157],"source":"set-2"},{"id":"set2-xpDxBel8","fingerprint":"691b8d79c553bb7c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este compoziția și structura finală a unei obturații de canal realizate prin tehnica de condensare laterală la rece?","options":[{"id":"A","text":"O rețea de conuri accesorii care înlocuiesc complet conul master pentru o mai bună adaptare."},{"id":"B","text":"Un singur con master adaptat perfect pereților canalului, cimentat cu o cantitate minimă de sealer."},{"id":"C","text":"Un mănunchi de conuri de gutapercă compactate, aderente prin fricțiune și sigilant, fără o omogenitate tridimensională reală."},{"id":"D","text":"O masă omogenă și compactă, rezultată din fuziunea la rece a conurilor de gutapercă."},{"id":"E","text":"O structură în care sigilantul formează componenta principală, iar conurile de gutapercă au rol de armătură."}],"correct":["C"],"pages":[157],"source":"set-2"},{"id":"set2-2xwXxWmH","fingerprint":"1c1794458f1c7dc7","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt dezavantajele tehnicii de condensare laterală la rece a gutapercii?","options":[{"id":"A","text":"Nu permite o sigilare apicală optimă."},{"id":"B","text":"Este o tehnică rapidă, recomandată în special pentru canalele cu curburi accentuate."},{"id":"C","text":"Conurile de gutapercă fuzionează într-o masă omogenă, eliminând necesitatea sigilantului."},{"id":"D","text":"Obturarea canalelor laterale și accesorii se realizează incomplet, doar cu sigilant."},{"id":"E","text":"Există un risc de fractură radiculară din cauza forțelor laterale exercitate de spreader."}],"correct":["A","D","E"],"pages":[158],"source":"set-2"},{"id":"set2-WyVIv_HQ","fingerprint":"6533477e6f7d3dfb","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În ce condiții se realizează proba conului master de gutapercă?","options":[{"id":"A","text":"Într-un canal lubrifiat cu un gel pe bază de EDTA."},{"id":"B","text":"Într-un canal umplut complet cu sigilant endodontic."},{"id":"C","text":"Într-un canal perfect uscat pentru a evalua corect fricțiunea."},{"id":"D","text":"Într-un canal irigat în prealabil cu hipoclorit de sodiu."},{"id":"E","text":"Într-un canal dezinfectat cu clorhexidină, imediat după preparare."}],"correct":["D"],"pages":[158],"source":"set-2"},{"id":"set2--gV0KMMi","fingerprint":"5a3ba5a8825c7a99","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt criteriile care trebuie respectate la proba clinico-radiologică a conului master?","options":[{"id":"A","text":"Criteriul tactil, manifestat prin senzația de \"tug-back\"."},{"id":"B","text":"Criteriul acustic, prin perceperea unui sunet specific la atingerea constricției apicale."},{"id":"C","text":"Criteriul vizual, prin corespondența reperului de pe con cu reperul ocluzal."},{"id":"D","text":"Criteriul radiologic, prin verificarea poziției vârfului conului la maximum 1mm de lungimea de lucru."},{"id":"E","text":"Criteriul cromatic, prin observarea culorii vârfului conului după inserare."}],"correct":["A","C","D"],"pages":[158],"source":"set-2"},{"id":"set2-i0Dx20ZD","fingerprint":"66493c740278fcd8","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce reprezintă senzația de \"tug-back\" în timpul probei conului master?","options":[{"id":"A","text":"Blocarea completă a conului la nivelul unei curburi a canalului."},{"id":"B","text":"Depășirea lungimii de lucru și contactul conului cu țesutul periapical."},{"id":"C","text":"Un indicator al prezenței de resturi dentinare în treimea apicală."},{"id":"D","text":"O ușoară rezistență la retragerea conului din canal, cauzată de fricțiunea apicală."},{"id":"E","text":"Contactul prematur al conului cu pereții coronari ai canalului."}],"correct":["D"],"pages":[158],"source":"set-2"},{"id":"set2-GIcOHtlv","fingerprint":"abbaf1dd5d9dfb46","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce presupune tehnica de individualizare a conului master?","options":[{"id":"A","text":"Utilizarea unui con cu dimensiuni imediat inferioare preparației apicale."},{"id":"B","text":"Este indicată în canalele înguste și curbe pentru a facilita inserția."},{"id":"C","text":"Ramolirea termică a vârfului conului și introducerea imediată în canal pentru a amprenta treimea apicală."},{"id":"D","text":"Secționarea repetată a vârfului conului până la obținerea senzației de \"tug-back\"."},{"id":"E","text":"Ramolirea chimică a vârfului conului cu cloroform pentru o adaptare perfectă."}],"correct":["C"],"pages":[158],"source":"set-2"},{"id":"set2-RPl5tKLb","fingerprint":"d2ec67cd71497527","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Cum se alege spreaderul în cazul canalelor radiculare lungi și curbe?","options":[{"id":"A","text":"Alegerea spreaderului nu este influențată de lungimea sau curbura canalului."},{"id":"B","text":"Se alege un spreader cu un diametru superior față de acul master."},{"id":"C","text":"Se utilizează exclusiv spreadere activate ultrasonic pentru a negocia curburile."},{"id":"D","text":"Se alege un spreader cu un diametru inferior față de acul master."},{"id":"E","text":"Se alege un spreader cu un diametru identic cu cel al acului master."}],"correct":["D"],"pages":[158],"source":"set-2"},{"id":"set2-VA4FT0qq","fingerprint":"9145565ecec8d9a2","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este diferența principală între conurile de gutapercă standardizate și cele nestandardizate?","options":[{"id":"A","text":"Conurile standardizate corespund instrumentarului manual (conicitate 2%), iar cele nestandardizate corespund instrumentarului rotativ (conicitate &gt;2%)."},{"id":"B","text":"Conurile standardizate au conicități variabile, în timp ce cele nestandardizate au o conicitate fixă de 2%."},{"id":"C","text":"Conurile nestandardizate sunt întotdeauna mai scurte decât cele standardizate."},{"id":"D","text":"Conurile nestandardizate sunt fabricate din gutapercă pură, iar cele standardizate conțin aditivi pentru radioopacitate."},{"id":"E","text":"Conurile standardizate sunt utilizate exclusiv pentru tehnici la cald, iar cele nestandardizate pentru tehnici la rece."}],"correct":["A"],"pages":[158],"source":"set-2"},{"id":"set2-GyNhxYJ-","fingerprint":"4aa9cb6e36400231","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce acțiune corectivă este necesară dacă, la proba vizuală, conul master depășește lungimea de lucru?","options":[{"id":"A","text":"Se îndoaie porțiunea apicală a conului pentru a scurta lungimea efectivă."},{"id":"B","text":"Se reia instrumentarea apicală cu un ac de diametru superior."},{"id":"C","text":"Se acceptă depășirea, considerând că sigilantul va compensa diferența."},{"id":"D","text":"Se alege un con cu o conicitate mai mare."},{"id":"E","text":"Conul va fi scurtat apical după redeterminarea diametrului apical al preparației."}],"correct":["E"],"pages":[158],"source":"set-2"},{"id":"set2-pGgEIH1G","fingerprint":"da195423124d1c05","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"La ce nivel se poziționează stoperul de pe spreader înaintea primei condensări laterale și care este justificarea acestei poziționări?","options":[{"id":"A","text":"La lungimea de lucru din care se scade 1 mm, deoarece primul milimetru apical va fi ocupat de vârful conului master."},{"id":"B","text":"La lungimea de lucru din care se scad 2 mm, pentru a preveni extruzia sigilantului."},{"id":"C","text":"La lungimea de lucru din care se scade 1 mm, deoarece spreaderul este mai scurt decât conurile accesorii."},{"id":"D","text":"La aceeași lungime cu cea a conului master, pentru a asigura o condensare uniformă."},{"id":"E","text":"La lungimea de lucru, deoarece spreaderul trebuie să ajungă la constricția apicală."}],"correct":["A"],"pages":[159],"source":"set-2"},{"id":"set2-niUeyRFz","fingerprint":"078f6d3d17f42496","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele caracteristici descriu un sigilant endodontic preparat corespunzător?","options":[{"id":"A","text":"Trebuie să curgă de pe spatulă în maxim 5 secunde când este menținută în poziție declivă."},{"id":"B","text":"Prezintă o consistență omogenă și cremoasă."},{"id":"C","text":"Poate fi menținut pe o spatulă în poziție declivă timp de 10 secunde fără să curgă."},{"id":"D","text":"Se poate extinde ca un fir pe aproximativ 2 cm între suportul de preparare și spatulă fără să fie întrerupt."},{"id":"E","text":"Este introdus în canal exclusiv prin acoperirea vârfului conului master."}],"correct":["B","C","D"],"pages":[159],"source":"set-2"},{"id":"set2-ZBVzZI60","fingerprint":"2bf24a0a9280b945","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce tehnică este recomandată pentru retragerea spreaderului din canalul radicular după compactarea conului master?","options":[{"id":"A","text":"O rotație continuă în sensul acelor de ceasornic."},{"id":"B","text":"O mișcare rapidă de tracțiune axială."},{"id":"C","text":"Menținerea presiunii axiale în timpul retragerii."},{"id":"D","text":"O rotație continuă în sens antiorar pentru a elimina excesul de sigilant."},{"id":"E","text":"Mișcări ușoare, de rotație reciprocă în sens orar și antiorar de câte 90°."}],"correct":["E"],"pages":[159],"source":"set-2"},{"id":"set2-M7F0YyOd","fingerprint":"0df517533d993f3a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce particularitate prezintă alegerea primului con accesor în cazul unui canal radicular lung și cu curburi accentuate?","options":[{"id":"A","text":"Se alege un con accesor de diametru inferior spreaderului utilizat."},{"id":"B","text":"Se indică alegerea unui con accesor de diametru superior spreaderului."},{"id":"C","text":"Se renunță la utilizarea conurilor accesorii în favoarea unei tehnici de obturare monocanal."},{"id":"D","text":"Se alege un con accesor cu aceeași conicitate și diametru ca spreaderul utilizat."},{"id":"E","text":"Se utilizează un con accesor acoperit complet cu sigilant, nu doar la vârf."}],"correct":["A"],"pages":[159],"source":"set-2"},{"id":"set2-QlnMHGeC","fingerprint":"37a4cf76cf70640f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la procedura de secționare a conurilor de gutapercă?","options":[{"id":"A","text":"Compactarea verticală finală se efectuează cu un plugger încălzit pentru a modela gutaperca."},{"id":"B","text":"Imediat după secționare se realizează compactarea verticală a gutapercii cu ajutorul unui plugger rece."},{"id":"C","text":"Secționarea se realizează cu un instrument electric suficient încălzit printr-o mișcare sigură și rapidă."},{"id":"D","text":"Instrumentul de secționare trebuie să fie rece pentru a preveni aderarea gutapercii."},{"id":"E","text":"Conurile se secționează individual pentru o mai mare precizie."}],"correct":["B","C"],"pages":[159],"source":"set-2"},{"id":"set2-VT5Zhxo2","fingerprint":"d8091c5375ba7f20","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este scopul menținerii spreaderului la lungimea de lucru timp de câteva secunde după ce a atins poziția finală?","options":[{"id":"A","text":"Pentru a verifica dacă lungimea de lucru a fost menținută corect."},{"id":"B","text":"Pentru a crea spațiul necesar conurilor accesorii."},{"id":"C","text":"Pentru a contracara tendința de desprindere a gutapercii dată de elasticitatea acesteia."},{"id":"D","text":"Pentru a permite sigilantului să pătrundă în canalele laterale."},{"id":"E","text":"Pentru a permite răcirea și solidificarea gutapercii în jurul său."}],"correct":["C"],"pages":[159],"source":"set-2"},{"id":"set2-uf38DbVd","fingerprint":"4fd4c553a44159a9","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Până la ce nivel este considerată completă umplerea canalului cu conuri accesorii în tehnica de condensare laterală?","options":[{"id":"A","text":"Până când primul con accesor ajunge la constricția apicală."},{"id":"B","text":"Până când spreaderul nu mai poate pătrunde deloc în canalul radicular."},{"id":"C","text":"Până când se observă refluarea sigilantului la nivelul orificiului de emergență."},{"id":"D","text":"Până când se introduc un număr de 3 conuri accesorii, indiferent de diametrul canalului."},{"id":"E","text":"Până când ultimul spreader va pătrunde numai în treimea coronară a canalului."}],"correct":["E"],"pages":[159],"source":"set-2"},{"id":"set2-tAyP8khl","fingerprint":"906deb6c4c6a6149","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"La ce nivel final trebuie să se situeze materialul de obturație (gutaperca) în porțiunea coronară a canalului după secționare și compactare verticală?","options":[{"id":"A","text":"La nivelul podelei camerei pulpare."},{"id":"B","text":"Exact la nivelul orificiului de emergență al canalului radicular."},{"id":"C","text":"La un nivel de 1 mm mai profund de orificiul de emergență al acestuia."},{"id":"D","text":"La nivelul joncțiunii smalț-dentină a dintelui."},{"id":"E","text":"La 2 mm coronar față de orificiul de emergență, pentru a lăsa spațiu pentru restaurare."}],"correct":["A","C"],"pages":[159],"source":"set-2"},{"id":"set2-2VsX_c5G","fingerprint":"6461883628864f0c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt dezavantajele tehnicii de obturație monocon?","options":[{"id":"A","text":"Rezultatele obținute nu sunt documentate de suficiente studii."},{"id":"B","text":"Un singur con nu se poate adapta la toate neregularitățile canalului radicular."},{"id":"C","text":"Necesită o cantitate crescută de sigilant pentru a compensa spațiile goale."},{"id":"D","text":"Este o tehnică lentă și nu respectă cu ușurință lungimea de lucru."},{"id":"E","text":"Este compatibilă exclusiv cu sigilanții pe bază de rășini epoxidice."}],"correct":["A","B","C"],"pages":[160],"source":"set-2"},{"id":"set2-tceThFVs","fingerprint":"fa56a8df9cac4134","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este scopul principal al tehnicii de condensare verticală la cald a gutapercii?","options":[{"id":"A","text":"Limitarea obturației strict la treimea coronară și medie a canalului radicular."},{"id":"B","text":"Realizarea unei obturații de canal omogene și compacte."},{"id":"C","text":"Utilizarea unui singur con de gutapercă corespunzător conicității preparației."},{"id":"D","text":"Reducerea timpului de lucru prin eliminarea pașilor de condensare."},{"id":"E","text":"Asigurarea unei preparații minime în treimea apicală, fără condensare în această zonă."}],"correct":["B"],"pages":[160],"source":"set-2"},{"id":"set2-4nOg1DuB","fingerprint":"ea2e23694408849e","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Conform variantei clasice a tehnicii de condensare verticală la cald, la ce distanță de limita apicală a preparației trebuie să ajungă conul master în timpul probei?","options":[{"id":"A","text":"La 3 mm."},{"id":"B","text":"La nivelul orificiului de emergență al canalului radicular."},{"id":"C","text":"La 4 - 6 mm."},{"id":"D","text":"La 0,5 - 2 mm."},{"id":"E","text":"Exact la limita apicală a preparației."}],"correct":["D"],"pages":[160],"source":"set-2"},{"id":"set2-z4axMMwb","fingerprint":"a4d2d871650ec5e4","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În tehnica clasică de condensare verticală la cald, ce acțiune urmează imediat după ce un instrument încălzit este introdus în masa de gutapercă, o secționează și îndepărtează o porțiune din aceasta?","options":[{"id":"A","text":"Introducerea unui plugger rece pentru a condensa vertical gutaperca restantă."},{"id":"B","text":"Secționarea conului la nivelul orificiului de emergență."},{"id":"C","text":"Termoinjectarea de gutapercă pentru a umple canalul."},{"id":"D","text":"Aplicarea sigilantului pentru a umple spațiul creat."},{"id":"E","text":"Introducerea unui nou con de gutapercă accesoriu."}],"correct":["A"],"pages":[160],"source":"set-2"},{"id":"set2-LJ5tXJmO","fingerprint":"d6ada5ad88bba352","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnica actuală de obturație de canal derivată din condensarea verticală la cald?","options":[{"id":"A","text":"Este o metodă hibridă care combină condensarea verticală (downpack) cu termoinjectarea (backfilling)."},{"id":"B","text":"Treimea apicală este obturată printr-un proces de condensare în sens corono-apical."},{"id":"C","text":"Întregul canal radicular este obturat prin introducerea succesivă de mici segmente de gutapercă."},{"id":"D","text":"Pentru încălzirea gutapercii se folosesc exclusiv spreadere manuale încălzite la flacără."},{"id":"E","text":"Porțiunea coronară și medie a canalului este umplută prin termoinjectare în sens apico-coronar."}],"correct":["A","B","E"],"pages":[160],"source":"set-2"},{"id":"set2-QjCKFdBX","fingerprint":"1837438b6f78cec5","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este lungimea segmentului de gutapercă ce trebuie condensat la nivel apical în ambele variante (clasică și actuală) ale tehnicii de condensare verticală la cald, înainte de a trece la obturarea restului canalului?","options":[{"id":"A","text":"2 - 4 mm"},{"id":"B","text":"0,5 - 2 mm"},{"id":"C","text":"Întreaga lungime de lucru minus 2 mm."},{"id":"D","text":"4 - 6 mm"},{"id":"E","text":"6 - 8 mm"}],"correct":["D"],"pages":[160],"source":"set-2"},{"id":"set2-ciMDzCSM","fingerprint":"7d94506a81a6d387","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt avantajele utilizării gutapercii încălzite în tehnicile de obturare a canalului radicular?","options":[{"id":"A","text":"Tehnica este mai puțin sensibilă la erori comparativ cu tehnicile la rece."},{"id":"B","text":"Elimină complet riscul de depășire a materialului de obturație."},{"id":"C","text":"Permite obturarea eventualelor canale laterale existente."},{"id":"D","text":"Gutaperca încălzită poate fi condensată în toate neregularitățile sistemului endodontic."},{"id":"E","text":"Se obține o obturație de canal completă, densă și omogenă."}],"correct":["C","D","E"],"pages":[161],"source":"set-2"},{"id":"set2-KkVnzvY9","fingerprint":"1c88929e74fe1033","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În cadrul tehnicii valului continuu de căldură, care este scopul menținerii presiunii apicale cu pluggerul dezactivat timp de 5-10 secunde?","options":[{"id":"A","text":"Pentru a activa proprietățile adezive ale conului master."},{"id":"B","text":"Pentru a contracara contracția gutapercii în cursul răcirii."},{"id":"C","text":"Pentru a asigura fuziunea conului master cu conurile accesorii."},{"id":"D","text":"Pentru a permite sigilantului să pătrundă în canalele laterale."},{"id":"E","text":"Pentru a verifica lungimea de lucru înainte de obturarea finală."}],"correct":["B"],"pages":[161],"source":"set-2"},{"id":"set2-iYcb42rQ","fingerprint":"fa7431ebaac59495","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce caracteristici sunt specifice tehnicii valului continuu de căldură, introdusă de Stephen Buchanan?","options":[{"id":"A","text":"Dezvoltă forțe hidraulice care determină o obturație tridimensională."},{"id":"B","text":"Utilizează pluggere încălzite electronic, de conicitate identică cu cea rezultată în urma instrumentării."},{"id":"C","text":"Pluggerul activat se introduce până la nivelul constricției apicale."},{"id":"D","text":"După compactarea porțiunii apicale, restul canalului se obturează prin condensare laterală la rece."},{"id":"E","text":"Este cunoscută și sub denumirea de \"condensare centrică\"."}],"correct":["A","B","E"],"pages":[161],"source":"set-2"},{"id":"set2-qE4EYCJl","fingerprint":"008916e7ba56d74c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care afirmație descrie corect tehnica condensării laterale la cald?","options":[{"id":"A","text":"Transmite tensiuni semnificative asupra pereților canalului radicular, similare condensării laterale la rece."},{"id":"B","text":"Utilizează dispozitive de tip spreader încălzite electronic pentru a fuziona conurile de gutapercă."},{"id":"C","text":"Este considerată inferioară condensării la rece din punct de vedere al obturației tridimensionale."},{"id":"D","text":"Utilizează exclusiv un plugger rece pentru compactarea conurilor de gutapercă."},{"id":"E","text":"Este mai puțin sensibilă la erori decât condensarea laterală la rece."}],"correct":["B"],"pages":[161],"source":"set-2"},{"id":"set2-HmGzapXu","fingerprint":"3674f906e5085fb7","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce aplicații au sistemele electronice de tip EndoTwinn în obturarea canalelor radiculare?","options":[{"id":"A","text":"Sunt destinate exclusiv pentru îndepărtarea materialelor de obturație vechi."},{"id":"B","text":"Permit aplicarea tehnicii de condensare verticală la cald."},{"id":"C","text":"Pot fi utilizate pentru aplicarea tehnicii de condensare laterală la cald."},{"id":"D","text":"Pot realiza simultan încălzirea și vibrațiile de joasă frecvență ale unor anse de tip plugger."},{"id":"E","text":"Sunt compatibile doar cu anse de o singură dimensiune și conicitate."}],"correct":["B","C","D"],"pages":[161],"source":"set-2"},{"id":"set2-Ui8n8Zjn","fingerprint":"d66467f5de7f0750","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În secvența operatorie a tehnicii valului continuu de căldură, ce manevră urmează imediat după activarea încălzirii pluggerului pentru o secundă și îndepărtarea acestuia din canal?","options":[{"id":"A","text":"Se începe direct obturarea restului canalului prin tehnica de termoinjectare."},{"id":"B","text":"Se introduce un nou con master pentru a completa obturația."},{"id":"C","text":"Se așteaptă 5-10 secunde pentru răcirea completă a gutapercii."},{"id":"D","text":"Se condensează imediat gutaperca cu un plugger rece."},{"id":"E","text":"Se introduce sigilant suplimentar în porțiunea coronară a canalului."}],"correct":["D"],"pages":[161],"source":"set-2"},{"id":"set2-hmsAHVSO","fingerprint":"00473bfbeb22fde3","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce tip de gutapercă și la ce temperatură este încălzită în dispozitivul utilizat pentru tehnica de termoinjectare?","options":[{"id":"A","text":"Gutapercă de tip α, încălzită la 185º - 200ºC."},{"id":"B","text":"Gutapercă de tip β, încălzită la 185º - 200ºC."},{"id":"C","text":"Gutapercă de tip β, încălzită la 210º - 225ºC."},{"id":"D","text":"Gutapercă de tip α, încălzită la 150º - 165ºC."},{"id":"E","text":"Gutaperca este introdusă la temperatura camerei și încălzită intraoral."}],"correct":["B"],"pages":[162],"source":"set-2"},{"id":"set2-lVM5l2_h","fingerprint":"efda8fa1c08bee2a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile corecte referitoare la procedura operatorie a tehnicii de termoinjectare a gutapercii?","options":[{"id":"A","text":"Sigilantul se aplică doar după obturarea completă a canalului radicular."},{"id":"B","text":"Condensarea verticală se realizează cu un plugger încălzit pentru a menține fluiditatea gutapercii."},{"id":"C","text":"Injectarea gutapercii se continuă retrăgând simultan canula, fără a fi necesară condensarea secvențială."},{"id":"D","text":"În timpul injectării, se menține o presiune în sens corono-apical până când acumularea de gutapercă determină o forță de împingere în sens apico-coronar."},{"id":"E","text":"Canula pentru injectare trebuie să pătrundă liber în canal până la o distanță de 3 - 5 mm de limita apicală a preparației."}],"correct":["D","E"],"pages":[162],"source":"set-2"},{"id":"set2-Si8xRCtw","fingerprint":"d800deeb5a9407e5","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce dezavantaje prezintă tehnica termoinjectării gutapercii?","options":[{"id":"A","text":"Existența riscului de depășire, ceea ce necesită o tehnică de condensare prealabilă în treimea apicală."},{"id":"B","text":"Necesitatea de a contracara contracția la răcire a gutapercii."},{"id":"C","text":"Dificultatea de a asigura un debit uniform de gutapercă, necesitând exersare."},{"id":"D","text":"Adaptare deficitară la geometria canalului radicular."},{"id":"E","text":"Imposibilitatea de a obtura canalele radiculare laterale."}],"correct":["A","B","C"],"pages":[162],"source":"set-2"},{"id":"set2-pk5txyoh","fingerprint":"3a9d5c0843eef411","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"În ce situații clinice specifice este avantajoasă utilizarea tehnicii de termoinjectare a gutapercii?","options":[{"id":"A","text":"Cazuri cu canale radiculare foarte curbe, unde canula nu poate fi inserată."},{"id":"B","text":"Obturarea situațiilor care prezintă resorbții radiculare interne."},{"id":"C","text":"Situații în care este esențială pătrunderea materialului de obturație în canalele radiculare laterale."},{"id":"D","text":"Cazuri în care se dorește evitarea contracției materialului de obturație."},{"id":"E","text":"Cazuri ce necesită o tehnică rapidă, cu o curbă de învățare minimă."}],"correct":["B","C"],"pages":[162],"source":"set-2"},{"id":"set2-32QGoeYW","fingerprint":"109cfd6e12e1c26f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este scopul principal al condensării verticale cu un plugger rece în cadrul tehnicii de termoinjectare a gutapercii?","options":[{"id":"A","text":"Verificarea adaptării gutapercii la pereții canalului."},{"id":"B","text":"Crearea unui sigiliu apical înainte de injectarea principală."},{"id":"C","text":"Împingerea gutapercii în canalele laterale."},{"id":"D","text":"Contracararea contracției la răcire a gutapercii."},{"id":"E","text":"Răcirea rapidă a canulei de injectare."}],"correct":["D"],"pages":[162],"source":"set-2"},{"id":"set2-CY20eAfP","fingerprint":"48fffc59def509d1","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este compoziția tijei (\"carrier\") și a stratului extern de gutapercă la cele mai recente sisteme de obturatoare de tip \"carrier-based\"?","options":[{"id":"A","text":"Tija este realizată dintr-un elastomer al gutapercii cu legături încrucișate, iar stratul extern este din gutapercă de tip β."},{"id":"B","text":"Tija este realizată din material plastic, iar stratul extern este din gutapercă de tip β."},{"id":"C","text":"Tija este realizată din oțel, iar stratul extern este din gutapercă de tip α."},{"id":"D","text":"Tija este realizată dintr-un elastomer al gutapercii cu legături încrucișate, iar stratul extern este din gutapercă de tip α."},{"id":"E","text":"Tija este realizată dintr-un aliaj de nichel-titan, iar stratul extern este din gutapercă de tip α."}],"correct":["D"],"pages":[163],"source":"set-2"},{"id":"set2-_KyCRz19","fingerprint":"be9411f33dabfbd9","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele situații reprezintă contraindicații pentru utilizarea tehnicii de obturare cu sisteme \"carrier-based gutta-percha\"?","options":[{"id":"A","text":"Resorbții radiculare interne."},{"id":"B","text":"Constricție apicală largă."},{"id":"C","text":"Canale curbe."},{"id":"D","text":"Canale în formă de \"C\"."},{"id":"E","text":"Bifurcații în treimea medie a canalului radicular."}],"correct":["A","B","D","E"],"pages":[163],"source":"set-2"},{"id":"set2-cgwyCTpw","fingerprint":"0dfc2ddf729c4c4f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Conform tehnicii operatorii de utilizare a sistemelor de obturatoare \"carrier-based\", care este procedura corectă după introducerea și propulsarea obturatorului în canalul radicular?","options":[{"id":"A","text":"Se așteaptă 10 minute pentru răcirea completă, după care se secționează obturatorul."},{"id":"B","text":"Se introduce imediat un instrument de verificare (\"verifier\") pentru a confirma poziția apicală."},{"id":"C","text":"Se secționează imediat obturatorul cu o freză specială, apoi se verifică radiologic rezultatul."},{"id":"D","text":"Se așteaptă 2 - 4 minute, se verifică radiologic rezultatul și apoi se secționează obturatorul."},{"id":"E","text":"Se condensează vertical gutaperca cu un plugger rece și apoi se verifică radiologic."}],"correct":["D"],"pages":[163],"source":"set-2"},{"id":"set2-i58sso_6","fingerprint":"3071aa2576bf1dd7","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt principiile și caracteristicile tehnicii de compactare termomecanică McSpadden?","options":[{"id":"A","text":"Necesită încălzirea prealabilă a gutapercii într-un cuptor special la o valoare predeterminată."},{"id":"B","text":"Utilizează un instrument rotativ, numit compactor McSpadden, cu o viteză de 8000 - 15000 de turații/min."},{"id":"C","text":"Compactorul are o parte activă similară unui ac Hedström inversat."},{"id":"D","text":"Căldura necesară ramolirii gutapercii este generată prin fricțiunea dintre compactor și gutapercă."},{"id":"E","text":"Condensarea gutapercii se realizează exclusiv în sens vertical."}],"correct":["B","C","D"],"pages":[163],"source":"set-2"},{"id":"set2-Fr542P3b","fingerprint":"5df91793787bd144","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"În cadrul tehnicii McSpadden, care sunt criteriile de selecție pentru conul master și pentru compactor?","options":[{"id":"A","text":"Atât conul master, cât și compactorul trebuie să aibă dimensiunea și conicitatea identice cu acul master."},{"id":"B","text":"Conul master are aceeași dimensiune ca acul master și ajunge la lungimea de lucru; compactorul are o dimensiune inferioară instrumentului de preparare apicală."},{"id":"C","text":"Conul master trebuie să poată fi introdus liber pe toată lungimea de lucru; compactorul se alege în funcție de curbura canalului."},{"id":"D","text":"Conul master are o dimensiune imediat superioară acului master; compactorul se introduce fără rotație până la reperul stabilit."},{"id":"E","text":"Conul master are o dimensiune superioară acului master și se introduce la 1,5 mm de lungimea de lucru; compactorul are aceeași dimensiune ca instrumentul de preparare apicală."}],"correct":["E"],"pages":[163],"source":"set-2"},{"id":"set2-fmhaqrNn","fingerprint":"720f7b08e59aca8f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect dezavantajele și riscurile tehnicii de compactare termomecanică McSpadden?","options":[{"id":"A","text":"Poate determina durere la inserție prin comprimarea apicală a aerului."},{"id":"B","text":"Este contraindicată în canalele curbe din cauza riscului de fracturare a compactorului."},{"id":"C","text":"Prezintă riscuri importante de supraîncălzire radiculară."},{"id":"D","text":"Este o tehnică lentă și dificil de învățat."},{"id":"E","text":"Există un risc de obturație cu depășire."}],"correct":["B","C","E"],"pages":[163],"source":"set-2"},{"id":"set2-9fQ2nvzE","fingerprint":"841bd9aea427a388","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce presupune tehnica combinată propusă de Tagger în 1984, ca alternativă la metoda clasică McSpadden?","options":[{"id":"A","text":"O succesiune de compactări termomecanice scurte pentru a evita depășirea materialului de obturație."},{"id":"B","text":"Compactare termomecanică în treimea apicală și condensare laterală în treimile medie și coronară."},{"id":"C","text":"Utilizarea unui compactor din aliaj de nichel-titan pentru a reduce riscul de supraîncălzire."},{"id":"D","text":"Aplicarea unui sigilant special cu priză rapidă înainte de compactarea termomecanică."},{"id":"E","text":"Condensare laterală în treimea apicală și compactare termomecanică în treimile medie și coronară."}],"correct":["E"],"pages":[163],"source":"set-2"},{"id":"set2-pr1qRVd4","fingerprint":"8e49102f36970146","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect etapele și componentele sistemului de obturație de canal MicroSeal?","options":[{"id":"A","text":"Conul master este condensat în prealabil prin tehnica la cald în treimea apicală."},{"id":"B","text":"Turația compactorului în timpul introducerii în canal este de 1000 - 4000 rotații/min."},{"id":"C","text":"Se utilizează un compactor din aliaj de nichel titan."},{"id":"D","text":"Gutaperca este plastifiată prin încălzire direct în interiorul canalului radicular."},{"id":"E","text":"Gutaperca utilizată pentru acoperirea compactorului este de faza α."}],"correct":["B","C","E"],"pages":[164],"source":"set-2"},{"id":"set2-0kSMQ-9n","fingerprint":"9e6eed6e0f700219","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Ce acțiune este considerată obligatorie după finalizarea oricărei tehnici de obturație de canal?","options":[{"id":"A","text":"Monitorizarea clinică a sensibilității dentare timp de 24 de ore."},{"id":"B","text":"Efectuarea unui test de vitalitate pulpară."},{"id":"C","text":"Monitorizarea radiologică pentru evaluarea în timp a rezultatelor."},{"id":"D","text":"Plasarea imediată a restaurării coronare definitive."},{"id":"E","text":"Verificarea radiologică a calității obturației."}],"correct":["E"],"pages":[164],"source":"set-2"},{"id":"set2-gskuruLN","fingerprint":"0ce4f69c666f0432","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Conform tehnicii sistemului MicroSeal, care este procedura specifică de preparare a conului de gutapercă master înainte de introducerea compactorului?","options":[{"id":"A","text":"Este acoperit cu gutapercă faza α și introdus simultan cu compactorul."},{"id":"B","text":"Este introdus în canal fără nicio condensare prealabilă."},{"id":"C","text":"Este condensat vertical la cald în treimea coronară a canalului."},{"id":"D","text":"Este încălzit împreună cu gutaperca α într-un dispozitiv extern."},{"id":"E","text":"Este condensat lateral la rece în treimea apicală cu un spreader din nichel titan."}],"correct":["E"],"pages":[164],"source":"set-2"},{"id":"set2-d4gxbA8q","fingerprint":"ed94681e0eec8df0","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt obiectivele și rolurile obturației de canal în cadrul tratamentului endodontic?","options":[{"id":"A","text":"Asigurarea sigilării exclusive a treimii apicale a sistemului endodontic pentru a permite adaptarea tisulară."},{"id":"B","text":"Permiterea conservării sau regăsirii stării de echilibru a structurilor parodontale înconjurătoare."},{"id":"C","text":"Favorizarea microinfiltrației fluide la nivel cervical pentru menținerea vitalității parodontale."},{"id":"D","text":"Întreruperea oricărei căi de comunicare a sistemului endodontic cu țesuturile parodontale și cavitatea orală."},{"id":"E","text":"Prevenirea oricărei posibilități de infecție sau reinfecție apicală și opoziția față de fenomenele de percolație."}],"correct":["B","D","E"],"pages":[151],"source":"set-2"},{"id":"set2-dgjw-fzy","fingerprint":"dd36fb1818c1629f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"În care dintre următoarele situații clinice este recomandată realizarea obturației de canal în aceeași ședință cu tratamentul chemo-mecanic?","options":[{"id":"A","text":"Dinte vital lipsit de patologie pulpară."},{"id":"B","text":"Dinte vital prezentând patologie pulpară."},{"id":"C","text":"Dinte devital asimptomatic."},{"id":"D","text":"Dinte simptomatic cu edem în contextul unei parodontite apicale acute."},{"id":"E","text":"Dinte cu secreție persistentă din spațiul periapical ce împiedică uscarea canalelor."}],"correct":["A","B","C"],"pages":[151],"source":"set-2"},{"id":"set2-PmVmy7aR","fingerprint":"4c9aca3eb8db012f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt situațiile clinice care impun temporizarea realizării obturației de canal de durată?","options":[{"id":"A","text":"Existența unui abces periapical acut asociat cu un dinte simptomatic."},{"id":"B","text":"Exudatul periapical persistent care face imposibilă uscarea canalelor radiculare."},{"id":"C","text":"Finalizarea preparării chemo-mecanice la un dinte vital cu patologie pulpară."},{"id":"D","text":"Prezența unei hemoragii din spațiul periapical care nu poate fi controlată."},{"id":"E","text":"Dintele prezintă lipsa vitalității și absența oricărui simptom clinic."}],"correct":["A","B","D"],"pages":[151],"source":"set-2"},{"id":"set2-cBvOfAZb","fingerprint":"1b63cc44df78c93b","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile asociate limitelor apicale ale obturației de canal și reperelor anatomice periapicale?","options":[{"id":"A","text":"Limita apicală a obturației de canal este în principiu acceptată ca fiind situată la o distanță de 1 mm de apexul radiologic."},{"id":"B","text":"Constricția apicală se află la o distanță medie de 0,5 mm de foramenul apical."},{"id":"C","text":"Foramenul apical este situat constant la o distanță de exact 1 mm de apexul radicular."},{"id":"D","text":"Constricția apicală poate fi determinată clinic cu precizie absolută fără ajutor radiologic."},{"id":"E","text":"Limita apicală a sistemului endodontic corespunde unei delimitări histologice reprezentate de joncțiunea cemento-dentinară."}],"correct":["A","B","E"],"pages":[151],"source":"set-2"},{"id":"set2-friPJjw4","fingerprint":"4b1eb3121a17ebad","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele particularități anatomice descrie cu acuratețe constricția apicală și relația topografică a acesteia?","options":[{"id":"A","text":"Este reprezentată de o structură cilindrică unică ce se află la o distanță medie de 1 mm de joncțiunea amelo-cementară."},{"id":"B","text":"Constituie o delimitare vizibilă clinic ce se suprapune constant cu joncțiunea cemento-dentinară și apexul radiologic."},{"id":"C","text":"Se localizează la o distanță medie de 0,5 mm de foramenul apical, care este situat la rândul său între 0 și 2,5 mm de apexul radicular."},{"id":"D","text":"Se găsește invariabil la nivelul apexului radicular, facilitând extinderea obturației la distanța exactă de 2,5 mm."},{"id":"E","text":"Are un aspect anatomic invariabil, caracterizat prin pereți dentinari divergenți către spațiul periapical."}],"correct":["C"],"pages":[151],"source":"set-2"},{"id":"set2-Rh_bhGAz","fingerprint":"a989d3e7e8470059","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la compoziția chimică și procentuală a gutapercii de uz endodontic?","options":[{"id":"A","text":"Cerurile și rășinile ocupă o proporție de 1-4% din compoziție și dețin rolul radioopacifiant al materialului."},{"id":"B","text":"Proporția de gutapercă propriu-zisă reprezintă 19-22% din structura chimică a conurilor destinate uzului endodontic."},{"id":"C","text":"Sulfații metalici se regăsesc în proporție de 1-17% și îndeplinesc exclusiv un rol de plastifiere a materialului."},{"id":"D","text":"Conține aproximativ 59-75% oxid de zinc, o concentrație care poate conferi materialului un caracter iritant."},{"id":"E","text":"Structura chimică a gutapercii corespunde izomerului 1,4, cis-poliisopren, extras din latexul lichid."}],"correct":["B","D"],"pages":[153],"source":"set-2"},{"id":"set2-bGChPqa7","fingerprint":"c4834ae7d538d3c3","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Formele cristaline ale gutapercii dictează modalitatea de utilizare în practica endodontică. Care este afirmația exactă referitoare la aceste proprietăți fizice?","options":[{"id":"A","text":"Forma cristalină α se utilizează de elecție în tehnicile termoplastice."},{"id":"B","text":"Forma cristalină α este utilizată pentru realizarea conurilor destinate metodelor aplicate la temperatură obișnuită."},{"id":"C","text":"Forma cristalină α prezintă capacitatea de a realiza o legătură chimică structurală cu sigilanții endodontici."},{"id":"D","text":"Forma cristalină β asigură caracterul adeziv al gutapercii la pereții dentinari în tehnica monocon."},{"id":"E","text":"Forma cristalină β este utilizată în mod curent în tehnicile termoplastice de obturare."}],"correct":["A"],"pages":[153],"source":"set-2"},{"id":"set2-4ET7hmAn","fingerprint":"95b22864062b570f","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Sigilanții pe bază de zinc-oxid eugenol (ZOE) reprezintă o clasă frecvent utilizată în endodonție. Care sunt caracteristicile asociate acestor materiale?","options":[{"id":"A","text":"Se caracterizează printr-o solubilitate redusă în mediul apos, menținându-și volumul în contact cu fluidele organismului."},{"id":"B","text":"Variantele comerciale de preparate care includ formaldehidă sunt cunoscute pentru efectul lor citotoxic."},{"id":"C","text":"Au un efect iritant asupra parodonțiului și dețin un potențial discromic asupra țesuturilor dentare dure."},{"id":"D","text":"Prezintă proprietăți antibacteriene conferite de prezența eugenolului."},{"id":"E","text":"Constituie un material stabil și neresorbabil în situația extruziei periapicale printr-o obturație de canal cu depășire."}],"correct":["B","C","D"],"pages":[154],"source":"set-2"},{"id":"set2-KwZBub27","fingerprint":"b2a1f8ecd097078b","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Pregătirea canalului radicular în vederea realizării obturației finale impune respectarea unor criterii stricte. Canalul radicular trebuie să fie:","options":[{"id":"A","text":"Decontaminat riguros prin intermediul izolării cu digă și al irigării corecte."},{"id":"B","text":"Complet lipsit de detritusuri, proces care implică îndepărtarea stratului de smear-layer."},{"id":"C","text":"Menținut ușor umed pentru a preveni desicarea și fisurarea dentinei radiculare."},{"id":"D","text":"Complet uscat înainte de introducerea materialului de obturație și a sigilantului."},{"id":"E","text":"Permeabil exclusiv în treimea sa apicală, pentru a limita extruzia sigilantului periapical."}],"correct":["A","B","D"],"pages":[152],"source":"set-2"},{"id":"set2-AZdhqBhl","fingerprint":"5bf15725d8a21951","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Materialele de tip rășinic precum Resilon și RealSeal au fost concepute ca o alternativă la gutapercă. Care este afirmația exactă referitoare la compoziția și mecanismul de acțiune al acestor materiale?","options":[{"id":"A","text":"Sunt materiale rigide, cu caracter corodabil, care predispun la eliberarea de compuși citotoxici la nivelul spațiului periapical."},{"id":"B","text":"Reprezintă un polimer natural extras din seva lăptoasă a arborelui Palaquium Gutta, modificat prin adăugarea de sticlă bioactivă."},{"id":"C","text":"Au la bază utilizarea formei cristaline α a policaprolactonei, structură special dezvoltată pentru tehnicile de condensare laterală la rece."},{"id":"D","text":"Constituie un polimer semi-cristalin sintetic termoplastic (policaprolactonă), care se asociază cu un sigilant rășinic pentru obținerea unei obturații monobloc."},{"id":"E","text":"Acționează ca o matrice rășinică autonomă, eliminând cu desăvârșire necesitatea interpunerii unui sigilant apical (sealer)."}],"correct":["D"],"pages":[154],"source":"set-2"},{"id":"set2-bRR9Ph_K","fingerprint":"83db149b5ea1c219","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Un sigilant endodontic (sealer) ideal trebuie să îndeplinească o serie de proprietăți fizico-chimice și biologice complexe. Care dintre următoarele calități se înscriu în profilul unui sigilant ideal?","options":[{"id":"A","text":"O priză caracterizată de contracție marcată, fenomen care facilitează avansarea mecanică a materialului în microspațiile endodontice."},{"id":"B","text":"Un timp de priză extrem de scurt, destinat prevenirii diluției materialului și a spălării acestuia de către fluidele periapicale."},{"id":"C","text":"Activitate bacteriostatică sau bactericidă, cu rol activ în blocarea microorganismelor reziduale la nivelul canaliculelor dentinare."},{"id":"D","text":"Un profil biologic ce include un caracter nonimunogen, nonmutagen și noncarcinogenetic."},{"id":"E","text":"Insolubilitatea în lichidele tisulare, aspect esențial pentru menținerea etanșeității tridimensionale a obturației radiculare."}],"correct":["C","D","E"],"pages":[154],"source":"set-2"},{"id":"set2-hK4PLRiF","fingerprint":"5025abba4d4deada","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice sigilanților pe bază de materiale bioceramice?","options":[{"id":"A","text":"Sunt materiale caracterizate prin hidrofobie marcată."},{"id":"B","text":"Manifestă o contracție de priză crescută după aplicare."},{"id":"C","text":"Reacția de priză se finalizează utilizând umiditatea de la nivelul dentinei."},{"id":"D","text":"Oferă un efect antibacterian de lungă durată, inclusiv asupra speciei bacteriene E. Faecalis."},{"id":"E","text":"Permit realizarea unei obturații de tip monobloc prin asocierea cu materialul Resilon."}],"correct":["C","D"],"pages":[156],"source":"set-2"},{"id":"set2-tcZtBPeC","fingerprint":"8a760d125e2f4f20","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care tip de sigilant endodontic prezintă un risc ridicat de detașare a materialului de obturație de la nivelul pereților canalului radicular, ca urmare a contracției de priză crescute?","options":[{"id":"A","text":"Sigilanții bazați pe rășini metacrilice"},{"id":"B","text":"Sigilanții bazați pe materiale bioceramice"},{"id":"C","text":"Sigilanții bazați pe materiale siliconice"},{"id":"D","text":"Sigilanții pe bază de rășini epoxidice"},{"id":"E","text":"Sigilanții pe bază de hidroxid de calciu"}],"correct":["A"],"pages":[155],"source":"set-2"},{"id":"set2-SIjkGO6V","fingerprint":"c28ba4f9da9fc03c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele fenomene reprezintă dezavantaje ale utilizării sigilanților pe bază de hidroxid de calciu?","options":[{"id":"A","text":"Solubilitatea în timp, fenomen care favorizează microinfiltrația."},{"id":"B","text":"Dificultatea majoră a îndepărtării totale din canalul radicular în situația reluării tratamentului endodontic."},{"id":"C","text":"Reacția de priză uneori neomogenă, cu material care rămâne de consistență păstoasă în anumite zone."},{"id":"D","text":"Eliberarea de formaldehidă în timpul reacției de priză, fenomen care generează citotoxicitate."},{"id":"E","text":"Lipsa adeziunii la pereții canalului radicular și la nivelul conurilor de gutapercă."}],"correct":["A","C","E"],"pages":[155],"source":"set-2"},{"id":"set2-B9SOqQdw","fingerprint":"77a3a20427c1b3cf","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"MTA (Mineral Trioxide Aggregate) este un material endodontic consacrat. Care dintre următoarele afirmații descriu proprietățile și indicațiile sale clinice?","options":[{"id":"A","text":"Reacția de priză se produce în mediu umed."},{"id":"B","text":"Conferă proprietăți de etanșeitate sistemului endodontic."},{"id":"C","text":"Este contraindicat în situațiile clinice care necesită abordări de tip apexificare."},{"id":"D","text":"Prezintă un nivel de pH acid, care îi scade biocompatibilitatea."},{"id":"E","text":"Structura sa chimică fundamentală se bazează pe un silicat de calciu bioactiv."}],"correct":["A","B","E"],"pages":[156],"source":"set-2"},{"id":"set2-zaz6tyKp","fingerprint":"1387977a379f91e1","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt caracteristicile clinice și fizico-chimice ale sigilanților bazați pe rășini metacrilice?","options":[{"id":"A","text":"Prezența monomerilor nepolimerizați manifestă toxicitate asupra țesuturilor periapicale."},{"id":"B","text":"Prezența umidității și a oxigenului interferează cu mecanismul de priză, crescând riscul de polimerizare incompletă."},{"id":"C","text":"Sunt mult mai dificil de îndepărtat din canalul radicular comparativ cu materialele pe bază de rășini epoxidice."},{"id":"D","text":"Induc citotoxicitate periapicală mediată exclusiv prin eliberarea formaldehidei."},{"id":"E","text":"Permit obținerea unei obturații de tip monobloc dacă sunt utilizați în asociere cu sistemul Resilon."}],"correct":["A","B","E"],"pages":[155],"source":"set-2"},{"id":"set2-sPbIcXyP","fingerprint":"412ca8947c20796a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la avantajele tehnicii de condensare laterală la rece a gutapercii?","options":[{"id":"A","text":"Tehnica presupune un timp de lucru redus și un consum minim de conuri de gutapercă."},{"id":"B","text":"Metoda asigură o sigilare apicală de bună calitate, perfect ermetică."},{"id":"C","text":"Introducerea conurilor și a cimentului de obturare se face într-un mod ușor de controlat clinic."},{"id":"D","text":"Se remarcă prin costuri scăzute de realizare a tratamentului."},{"id":"E","text":"Procedura este predictibilă, eficientă și ușor de învățat."}],"correct":["C","D","E"],"pages":[157],"source":"set-2"},{"id":"set2-tkosut8E","fingerprint":"88b9703a74763202","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele afirmații este adevărată referitor la proba conului master în tehnica de condensare laterală la rece?","options":[{"id":"A","text":"Evaluarea radiologică impune poziționarea vârfului conului la o distanță de maximum 2 mm față de constricția apicală anatomică."},{"id":"B","text":"Proba conului master se realizează exclusiv într-un canal complet uscat, pentru a preveni alunecarea acestuia."},{"id":"C","text":"Criteriul vizual presupune evaluarea adaptării ermetice prin refluarea cimentului de sigilare la nivel ocluzal."},{"id":"D","text":"Dacă reperul de pe con depășește lungimea de lucru, scurtarea se realizează exclusiv prin ramolirea sa termică la nivelul constricției."},{"id":"E","text":"Criteriul tactil presupune prezența unei ușoare rezistențe la retragerea din canal, fenomen datorat fricțiunii din imediata vecinătate a constricției apicale."}],"correct":["E"],"pages":[158],"source":"set-2"},{"id":"set2-s748EexD","fingerprint":"a92c9dd11d5e3355","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la dezavantajele și limitările condensării laterale la rece a gutapercii?","options":[{"id":"A","text":"Tehnica nu este recomandată în situația existenței unei preparații radiculare fără stop apical."},{"id":"B","text":"Tehnica asigură cu ușurință obturarea ramificațiilor endodontice cu gutapercă pe toată lungimea de lucru."},{"id":"C","text":"Gutaperca devine o masă compactă și omogenă care refulează în canaliculele dentinare sub presiunea spreaderului."},{"id":"D","text":"Există un risc de fractură radiculară ca urmare a forțelor laterale concentrate în jurul vârfului spreaderului."},{"id":"E","text":"Condensarea conurilor accesorii lângă conul master este adesea dificilă în treimea apicală a canalului radicular."}],"correct":["A","D","E"],"pages":[158],"source":"set-2"},{"id":"set2-Fd6Z6bab","fingerprint":"bc2c763ecdef9930","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele afirmații descrie corect o etapă sau o proprietate materială necesară în cursul procedurii de introducere a sigilantului în canalul radicular?","options":[{"id":"A","text":"Aplicarea cu acul Kerr necesită depunerea cimentului exclusiv prin intermediul unei presiuni apicale intense."},{"id":"B","text":"Sigilantul prezintă consistența optimă atunci când poate fi menținut pe spatulă în poziție declivă timp de 1 minut fără să curgă."},{"id":"C","text":"Consistența cremoasă este validată dacă sigilantul se poate extinde continuu ca un fir de cel puțin 5 cm de pe placa de preparare."},{"id":"D","text":"Înainte de a fi acoperit cu sigilant, conul master este scufundat pentru decontaminare timp de 5 minute în clorhexidină."},{"id":"E","text":"Introducerea sigilantului pe pereții canalului se poate efectua folosind un ac Lentulo care este retras din spațiul endodontic în stare de rotație."}],"correct":["E"],"pages":[159],"source":"set-2"},{"id":"set2-kkbe-M0S","fingerprint":"29addd204584a746","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce protocoale de operare caracterizează compactarea conurilor de gutapercă și etapele finale ale tehnicii de condensare laterală la rece?","options":[{"id":"A","text":"Secționarea conurilor de la nivel coronar impune aplicarea unui instrument electric suficient încălzit printr-o acțiune sigură și rapidă."},{"id":"B","text":"Retragerea spreaderului din masa de gutapercă se execută prin aplicarea unor mișcări de rotație reciprocă orară și antiorară de câte 90°."},{"id":"C","text":"Compactarea verticală finală de la orificiul de emergență se desfășoară exclusiv cu utilizarea unui plugger preîncălzit."},{"id":"D","text":"Primul con accesor selectat trebuie să aibă constant un diametru superior spreaderului, pentru o umplere densă."},{"id":"E","text":"La prima inserare, stoperul spreaderului este poziționat fix la valoarea lungimii de lucru din care s-a scăzut 1 mm."}],"correct":["A","B","E"],"pages":[159],"source":"set-2"},{"id":"set2-rbvEPUaK","fingerprint":"1f6f5956fbd88e4a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este distanța față de limita apicală a preparației la care trebuie să ajungă conul master în etapa de selecție și probă din varianta clasică a tehnicii de condensare verticală la cald?","options":[{"id":"A","text":"1 - 2 mm"},{"id":"B","text":"Până la nivelul exact al limitei apicale"},{"id":"C","text":"1,5 - 3 mm"},{"id":"D","text":"0,5 - 1 mm"},{"id":"E","text":"0,5 - 2 mm"}],"correct":["E"],"pages":[160],"source":"set-2"},{"id":"set2-ksW34fWz","fingerprint":"c3afbd05487eb838","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt pașii procedurali caracteristici tehnicii valului continuu de căldură?","options":[{"id":"A","text":"După dezactivarea încălzirii, pluggerul este retras imediat din canalul radicular."},{"id":"B","text":"Introducerea pluggerului activat se realizează pe o lungime cu 5 mm inferioară lungimii de lucru."},{"id":"C","text":"Înainte de îndepărtarea din canal, încălzirea pluggerului se activează timp de o secundă sub menținerea presiunii apicale."},{"id":"D","text":"Presiunea apicală se menține cu încălzirea dezactivată timp de 5 - 10 secunde."},{"id":"E","text":"Introducerea pluggerului activat se realizează printr-o mișcare continuă apico-coronară."}],"correct":["B","C","D"],"pages":[161],"source":"set-2"},{"id":"set2-3qdEmc1x","fingerprint":"bbff172a19a168d2","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect tehnica termoinjectării gutapercii (backfilling)?","options":[{"id":"A","text":"Canula de injectare trebuie să pătrundă liber în canal până la o distanță de 3 - 5 mm de limita apicală a preparației."},{"id":"B","text":"Imposibilitatea obturării situațiilor clinice cu resorbții radiculare interne reprezintă un dezavantaj major."},{"id":"C","text":"Injectarea gutapercii se aplică prioritar pentru obturarea treimii apicale a canalului radicular."},{"id":"D","text":"Materialul de obturație se încălzește extraoral la o temperatură cuprinsă între 185º și 200º."},{"id":"E","text":"Gutaperca utilizată este de tip β, prezentată sub formă de pelete."}],"correct":["A","D","E"],"pages":[162],"source":"set-2"},{"id":"set2-X1hMdiP7","fingerprint":"8e4343fd7f603e38","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele aspecte reprezintă un dezavantaj al tehnicii de obturație monocon?","options":[{"id":"A","text":"Dificultatea menținerii constante a lungimii de lucru pe parcursul inserției conului."},{"id":"B","text":"Un con unic nu poate corespunde tuturor neregularităților canalului radicular."},{"id":"C","text":"Transmiterea unor tensiuni extreme asupra pereților canalului radicular."},{"id":"D","text":"Timpul operator mult prelungit comparativ cu tehnica de condensare verticală la cald."},{"id":"E","text":"Utilizarea tehnicii limitează exclusiv posibilitatea asocierii cu sigilanții pe bază de rășini epoxidice."}],"correct":["B"],"pages":[161],"source":"set-2"},{"id":"set2-sWRqT2FY","fingerprint":"03a25e223626f9c3","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt caracteristicile tehnicii de condensare laterală la cald?","options":[{"id":"A","text":"Transmite tensiuni semnificativ mai mari asupra pereților canalului radicular comparativ cu tehnica la rece."},{"id":"B","text":"Implică utilizarea unui spreader rece după compactarea laterală a conului master cu un instrument încălzit."},{"id":"C","text":"Realizează o fuzionare reală a conurilor de gutapercă încălzite."},{"id":"D","text":"Permite obturarea canalelor radiculare laterale."},{"id":"E","text":"Este caracterizată printr-o sensibilitate mai redusă la erori față de condensarea laterală la rece."}],"correct":["B","C","D"],"pages":[161],"source":"set-2"},{"id":"set2-Q0T_fwK5","fingerprint":"0418b492d6020fe9","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care este compoziția celor mai recente sisteme de obturatoare pe suport (carrier-based gutta-percha)?","options":[{"id":"A","text":"Tijă dintr-un elastomer al gutapercii cu legături încrucișate și un strat extern din gutapercă de tip α."},{"id":"B","text":"Tijă din titan acoperită cu gutapercă de tip α și β amestecate uniform."},{"id":"C","text":"Tijă dintr-un elastomer de silicon cu strat extern din material plastic termoplastic."},{"id":"D","text":"Tijă din material plastic acoperită cu un strat intern de sigilant."},{"id":"E","text":"Tijă din oțel acoperită exclusiv cu gutapercă de tip β."}],"correct":["A"],"pages":[162],"source":"set-2"},{"id":"set2-FB-gvee4","fingerprint":"bb58fa6324bf3f52","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt etapele specifice tehnicii operatorii în utilizarea sistemelor de obturatoare pe suport?","options":[{"id":"A","text":"Secționarea obturatorului la nivelul orificiului de emergență imediat după introducerea acestuia în canal."},{"id":"B","text":"Propulsarea imediată a obturatorului cu o presiune fermă în sens apical, după încălzire."},{"id":"C","text":"Utilizarea unui instrument de verificare care trebuie să poată fi introdus liber pe toată lungimea de lucru."},{"id":"D","text":"Tăierea tijei utilizând exclusiv o freză sferică montată la piesa dreaptă."},{"id":"E","text":"Aplicarea unei cantități limitate de sigilant la nivelul pereților canalului radicular."}],"correct":["B","C","E"],"pages":[163],"source":"set-2"},{"id":"set2-dBk4bd3f","fingerprint":"a4e98545fabdd54e","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce avantaje prezintă sistemele de obturatoare pe suport în endodonție?","options":[{"id":"A","text":"Inducerea unor tensiuni reduse și controlabile la nivelul pereților radiculari în timpul aplicării."},{"id":"B","text":"Constituirea unei tehnici de lucru rapide."},{"id":"C","text":"Flexibilitatea obturatoarelor care permite negocierea și obturarea canalelor curbe."},{"id":"D","text":"Permisiunea de a fi utilizate ca tratament de primă intenție în caz de resorbții radiculare interne."},{"id":"E","text":"Realizarea unei obturații tridimensionale prin pătrunderea gutapercii ramolite în neregularitățile sistemului endodontic."}],"correct":["B","C","E"],"pages":[163],"source":"set-2"},{"id":"set2-rY7hjZOn","fingerprint":"7877e215e15fc16a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele aspecte reprezintă contraindicații sau dezavantaje ale sistemelor de obturatoare pe suport?","options":[{"id":"A","text":"Situațiile clinice care prezintă o constricție apicală largă."},{"id":"B","text":"Apariția durerii la inserție din cauza comprimării apicale a aerului aflat în canalul radicular."},{"id":"C","text":"Sistemele endodontice caracterizate de canale în formă de „C”."},{"id":"D","text":"Imposibilitatea obturării canalelor radiculare cu grad de curbură moderată spre severă."},{"id":"E","text":"Canalele radiculare care prezintă bifurcații situate în treimea medie."}],"correct":["A","B","C","E"],"pages":[163],"source":"set-2"},{"id":"set2-kvgy861Y","fingerprint":"db764a3b85fc0b4a","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt etapele procedurale specifice tehnicii clasice de compactare termomecanică McSpadden?","options":[{"id":"A","text":"Compactorul se introduce în canal de-a lungul conului de gutapercă fiind deja activat în rotație continuă."},{"id":"B","text":"Condensarea verticală a gutapercii din treimea coronară se realizează imediat cu un plugger încălzit la roșu."},{"id":"C","text":"Conul master trebuie să pătrundă în canal pe o lungime cu 1,5 mm mai mică decât lungimea de lucru."},{"id":"D","text":"Dimensiunea compactorului trebuie să fie imediat inferioară instrumentului utilizat pe ultimii 2 mm apicali."},{"id":"E","text":"Retragerea compactorului din canalul radicular se realizează lent, menținând instrumentul în rotație."}],"correct":["C","E"],"pages":[163],"source":"set-2"},{"id":"set2-wtGatORe","fingerprint":"9680595d89689202","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care dintre următoarele afirmații descriu corect metodele alternative dezvoltate pentru compensarea dezavantajelor tehnicii McSpadden?","options":[{"id":"A","text":"Tehnica combinată Tagger asociază condensarea laterală în treimea apicală cu compactarea termomecanică în treimile medie și coronară."},{"id":"B","text":"Sistemul MicroSeal utilizează un compactor acoperit cu gutapercă faza β plastifiată termic direct în canalul radicular."},{"id":"C","text":"Tehnica combinată a fost concepută pentru a substitui complet verificarea radiologică postoperatorie."},{"id":"D","text":"În sistemul MicroSeal, conul master necesită o condensare laterală prealabilă la rece în treimea apicală."},{"id":"E","text":"Turația compactorului în sistemul MicroSeal este fixată între 8000 și 15000 de rotații/minut."}],"correct":["A","D"],"pages":[163],"source":"set-2"},{"id":"set2-m5rXEx-g","fingerprint":"61308faba09e977c","chapterId":"set-2","subchapterId":"set2-2.05","type":"CS","text":"Care dintre următoarele afirmații descrie cel mai precis un dezavantaj major sau o limitare a tehnicii clasice de compactare termomecanică McSpadden?","options":[{"id":"A","text":"Ineficiența în pătrunderea materialului, ducând frecvent la o obturație neomogenă a canalelor laterale."},{"id":"B","text":"Necesitatea preplastifierii gutapercii într-un dispozitiv extern anterior introducerii pe canalul radicular."},{"id":"C","text":"Riscul crescut de supraîncălzire radiculară și probabilitatea obținerii unei obturații cu depășire."},{"id":"D","text":"Imposibilitatea utilizării de conuri din gutapercă, fiind compatibilă doar cu sigilanți pe bază de rășini epoxidice."},{"id":"E","text":"Timpul îndelungat de lucru necesar pentru ramolirea gutapercii exclusiv prin fricțiune intra-radiculară."}],"correct":["C"],"pages":[163],"source":"set-2"},{"id":"set2-CFrPA03i","fingerprint":"82016f53c8f72d25","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Ce parametri definitorii prezintă instrumentarul și materialele folosite în tehnica clasică de compactare termomecanică McSpadden?","options":[{"id":"A","text":"Dimensiunea și conicitatea compactorului sunt identice cu cele ale instrumentului utilizat pe ultimii 2 mm apicali."},{"id":"B","text":"Dimensiunea conului master trebuie să fie exact identică cu dimensiunea acului master."},{"id":"C","text":"Compactorul este utilizat strict de-a lungul unui spreader din nichel titan pe parcursul fazei de rotație."},{"id":"D","text":"Compactorul prezintă o parte activă similară unui ac Hedström inversat."},{"id":"E","text":"Turația instrumentului rotativ este cuprinsă între 8000 și 15000 de turații/minut."}],"correct":["A","D","E"],"pages":[163],"source":"set-2"},{"id":"set2-_-VuBQz5","fingerprint":"1ecec3400b4b4963","chapterId":"set-2","subchapterId":"set2-2.05","type":"CM","text":"Care sunt principiile fundamentale de acțiune și de conduită clinică asociate tehnicilor de compactare termomecanică a gutapercii?","options":[{"id":"A","text":"Căldura necesară ramolirii în tehnica clasică provine din preîncălzirea pătii active a compactorului la o sursă externă."},{"id":"B","text":"Tehnica clasică are ca indicație de elecție obturarea canalelor curbe, datorită flexibilității superioare a instrumentului la 15000 turații/minut."},{"id":"C","text":"Conul master din tehnica clasică trebuie acoperit la vârf cu sigilant înainte de introducerea până la reperul stabilit."},{"id":"D","text":"Sistemul MicroSeal exclude utilizarea conului master de gutapercă, compactarea realizându-se doar din gutaperca aplicată pe compactor."},{"id":"E","text":"În tehnica clasică, condensarea laterală și verticală a gutapercii are loc simultan cu ramolirea sa termică."}],"correct":["C","E"],"pages":[163],"source":"set-2"}];
